import java.sql.Connection;
import java.sql.DriverManager;
import java.sql.PreparedStatement;
import java.sql.ResultSet;
import java.sql.SQLException;
import java.sql.Statement;
import java.util.Scanner;

public class BankAccountSystem {
    private static Connection connection;

    public static void main(String[] args) {
        try {
            connect();
            createTable();

            Scanner scanner = new Scanner(System.in);
            while (true) {
                System.out.println("1. Create Account");
                System.out.println("2. Deposit Money");
                System.out.println("3. Withdraw Money");
                System.out.println("4. Check Balance");
                System.out.println("5. Exit");

                int choice = scanner.nextInt();
                scanner.nextLine(); // Consume newline

                switch (choice) {
                    case 1:
                        createAccount(scanner);
                        break;
                    case 2:
                        depositMoney(scanner);
                        break;
                    case 3:
                        withdrawMoney(scanner);
                        break;
                    case 4:
                        checkBalance(scanner);
                        break;
                    case 5:
                        return;
                    default:
                        System.out.println("Invalid option.");
                }
            }
        } catch (SQLException e) {
            System.err.println(e.getMessage());
        } finally {
            try {
                if (connection != null) {
                    connection.close();
                }
            } catch (SQLException e) {
                System.err.println(e.getMessage());
            }
        }
    }

    private static void connect() throws SQLException {
        String url = "jdbc:sqlite:bank_account_system.db";
        connection = DriverManager.getConnection(url);
    }

    private static void createTable() throws SQLException {
        String sql = "CREATE TABLE IF NOT EXISTS accounts (" +
                "username TEXT PRIMARY KEY," +
                "password TEXT NOT NULL," +
                "balance REAL NOT NULL)";
        Statement stmt = connection.createStatement();
        stmt.execute(sql);
    }

    private static void createAccount(Scanner scanner) throws SQLException {
        System.out.print("Enter username: ");
        String username = scanner.nextLine();

        System.out.print("Enter password: ");
        String password = scanner.nextLine();

        String sql = "INSERT INTO accounts (username, password, balance) VALUES (?, ?, ?)";
        PreparedStatement pstmt = connection.prepareStatement(sql);
        pstmt.setString(1, username);
        pstmt.setString(2, password);
        pstmt.setDouble(3, 0.0);

        if (pstmt.executeUpdate() > 0) {
            System.out.println("Account created successfully.");
        } else {
            System.err.println("Failed to create account.");
        }
    }

    private static void depositMoney(Scanner scanner) throws SQLException {
        System.out.print("Enter username: ");
        String username = scanner.nextLine();

        System.out.print("Enter password: ");
        String password = scanner.nextLine();

        double currentBalance = getBalance(username, password);
        if (currentBalance < 0) {
            System.err.println("Invalid credentials.");
            return;
        }

        System.out.print("Enter amount to deposit: ");
        double amount = scanner.nextDouble();
        scanner.nextLine(); // Consume newline

        updateBalance(username, password, currentBalance + amount);
        System.out.println("Deposit successful.");
    }

    private static void withdrawMoney(Scanner scanner) throws SQLException {
        System.out.print("Enter username: ");
        String username = scanner.nextLine();

        System.out.print("Enter password: ");
        String password = scanner.nextLine();

        double currentBalance = getBalance(username, password);
        if (currentBalance < 0) {
            System.err.println("Invalid credentials.");
            return;
        }

        System.out.print("Enter amount to withdraw: ");
        double amount = scanner.nextDouble();
        scanner.nextLine(); // Consume newline

        if (amount > currentBalance) {
            System.err.println("Insufficient balance.");
            return;
        }

        updateBalance(username, password, currentBalance - amount);
        System.out.println("Withdrawal successful.");
    }

    private static void checkBalance(Scanner scanner) throws SQLException {
        System.out.print("Enter username: ");
        String username = scanner.nextLine();

        System.out.print("Enter password: ");
        String password = scanner.nextLine();

        double balance = getBalance(username, password);
        if (balance < 0) {
            System.err.println("Invalid credentials.");
        } else {
            System.out.printf("Current balance: %.2f%n", balance);
        }
    }

    private static double getBalance(String username, String password) throws SQLException {
        String sql = "SELECT balance FROM accounts WHERE username = ? AND password = ?";
        PreparedStatement pstmt = connection.prepareStatement(sql);
        pstmt.setString(1, username);
        pstmt.setString(2, password);

        ResultSet rs = pstmt.executeQuery();
        if (rs.next()) {
            return rs.getDouble("balance");
        } else {
            return -1.0;
        }
    }

    private static void updateBalance(String username, String password, double newBalance) throws SQLException {
        String sql = "UPDATE accounts SET balance = ? WHERE username = ? AND password = ?";
        PreparedStatement pstmt = connection.prepareStatement(sql);
        pstmt.setDouble(1, newBalance);
        pstmt.setString(2, username);
        pstmt.setString(3, password);

        pstmt.executeUpdate();
    }
}

