Here is a simple implementation of a TCP server in GoLang that accepts client connections and allows clients to get or set key-value pairs. It uses a map as an in-memory database.

```go
package main

import (
	"bufio"
	"fmt"
	"net"
	"strings"
)

var db = make(map[string]string)

func handleConnection(c net.Conn) {
	fmt.Printf("Serving %s\n", c.RemoteAddr().String())
	for {
		netData, err := bufio.NewReader(c).ReadString('\n')
		if err != nil {
			fmt.Println(err)
			return
		}

		command := strings.TrimSpace(string(netData))
		tokens := strings.Split(command, " ")

		switch tokens[0] {
		case "GET":
			c.Write([]byte(db[tokens[1]] + "\n"))
		case "SET":
			db[tokens[1]] = tokens[2]
		default:
			c.Write([]byte("INVALID COMMAND\n"))
		}
	}
	c.Close()
}

func main() {
	PORT := ":8080"
	l, err := net.Listen("tcp4", PORT)
	if err != nil {
		fmt.Println(err)
		return
	}
	defer l.Close()

	fmt.Println("Server listening on ", PORT)

	for {
		c, err := l.Accept()
		if err != nil {
			fmt.Println(err)
			continue
		}
		go handleConnection(c)
	}
}
```

